	private static List<Statement> seedPublishedStages(AcknowledgedStore store, long baseline) throws Exception {
		CountDownLatch selected = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
		publisher.setBeforePublication(() -> {
			selected.countDown();
			try {
				assertTrue(release.await(20, TimeUnit.SECONDS));
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
				throw new AssertionError(interrupted);
			}
		});
		store.notifyAcknowledgementAt.set(baseline + SEED_STAGES);
		List<Statement> statements = seedStatements();
		try {
			for (int index = 0; index < statements.size(); index++) {
				add(store, statements.get(index));
				LmdbBackupFallbackTestSupport.assertStripedFrame(store.getBackingStore().getTripleStore(),
						baseline + index + 1);
				if (index == 0) {
					assertTrue(selected.await(20, TimeUnit.SECONDS));
				}
			}
		} finally {
			publisher.setBeforePublication(() -> {
			});
			release.countDown();
		}
		assertTrue(store.acknowledgementReached.await(20, TimeUnit.SECONDS));
		assertEquals(baseline + SEED_STAGES, publisher.acknowledgedTransactionId());
		assertEquals(SEED_STAGES,
				store.getBackingStore().getTripleStore().listBackupStageTransactions(baseline, Long.MAX_VALUE).size());
		return statements;
	}

	private static List<Statement> seedStatements() {
		List<Statement> statements = new ArrayList<>();
		for (int index = 1; index <= SEED_STAGES; index++) {
			statements.add(fallbackStatement("seed-" + index));
		}
		return statements;
	}

	private static Stage stage(TripleStore triples, long transaction) throws IOException {
		return PostCommitBackupPublisher.readStage(new DataInputStream(new ByteArrayInputStream(
				triples.readBackupStageHeader(transaction))), null);
	}

	private static void assertExported(LmdbStore store, Path backups, long baseline, List<Statement> statements,
			Path destination) throws IOException {
		List<Path> logs = ((LmdbBackupServiceImpl) store.getBackupService()).exportTransactionLogs(backups, baseline,
				baseline + statements.size(), destination);
		assertEquals(statements.size(), logs.size());
		for (int index = 0; index < statements.size(); index++) {
			ByteArrayOutputStream expected = new ByteArrayOutputStream();
			LmdbBackupDeltaCodec.write(expected, List.of(new Record(true, true, statements.get(index))),
					baseline + index,
					store.getBackingStore().backupJournalState().generation());
			try (var input = new GZIPInputStream(Files.newInputStream(logs.get(index)))) {
				assertArrayEquals(expected.toByteArray(), input.readAllBytes());
			}
		}
	}

	private static byte[] nativeAcknowledgement(TripleStore triples) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			var database = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, TripleStore.NAMESPACE_DATABASE_NAME, 0, database));
			MDBVal key = MDBVal.malloc(stack).mv_data(stack.bytes(NATIVE_ACK_KEY));
			MDBVal value = MDBVal.malloc(stack);
			int result = mdb_get(transaction, database.get(0), key, value);
			if (result == MDB_NOTFOUND) {
				return null;
			}
			E(result);
			byte[] copy = new byte[(int) value.mv_size()];
			value.mv_data().get(copy);
			return copy;
		});
	}

	private static boolean hasStageChunk(long transaction, long logicalTransaction) {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			var database = stack.mallocInt(1);
			int bucket = (int) (logicalTransaction & (LmdbBackupOutbox.BUCKET_COUNT - 1));
			assertEquals(MDB_SUCCESS,
					mdb_dbi_open(transaction, LmdbBackupOutbox.bucketDatabaseName(bucket), 0, database));
			MDBVal key = MDBVal.malloc(stack)
					.mv_data(stack.malloc(2 * Long.BYTES)
							.order(ByteOrder.BIG_ENDIAN)
							.putLong(logicalTransaction)
							.putLong(0)
							.flip());
			MDBVal value = MDBVal.malloc(stack);
			int result = mdb_get(transaction, database.get(0), key, value);
			if (result == MDB_NOTFOUND) {
				return false;
			}
			assertEquals(MDB_SUCCESS, result);
			return true;
		}
	}

	private static PostCommitBackupPublisher.Acknowledgement readAcknowledgement(byte[] bytes, int magic)
			throws IOException {
		assertEquals(Integer.BYTES + 3 * Long.BYTES, bytes.length,
				"The native proof must contain one complete UUID/transaction pair");
		try (DataInputStream input = new DataInputStream(new ByteArrayInputStream(bytes))) {
			assertEquals(magic, input.readInt());
			UUID identity = new UUID(input.readLong(), input.readLong());
			long transaction = input.readLong();
			assertTrue(transaction >= 0);
			assertEquals(-1, input.read());
			return new PostCommitBackupPublisher.Acknowledgement(identity, transaction);
		}
	}

	private static Statement statement(String name) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:native-ack:" + name),
				values.createIRI("urn:native-ack:p"), values.createLiteral(name));
	}

	private static Statement fallbackStatement(String name) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:native-ack:" + name),
				values.createIRI("urn:native-ack:p"),
				values.createLiteral(LmdbBackupFallbackTestSupport.label(name)));
	}

	private static void add(LmdbStore store, Statement statement) {
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
			connection.commit();
		}
	}

	private static final class AcknowledgedStore extends LmdbStore {
		private final AtomicLong notifyAcknowledgementAt = new AtomicLong(Long.MAX_VALUE);
		private final CountDownLatch acknowledgementReached = new CountDownLatch(1);

		private AcknowledgedStore(Path directory) {
			super(directory.toFile(), new LmdbStoreConfig().setBackupJournalEnabled(true));
		}

		@Override
		LmdbSailStore createBackingStore(File data, StoreProperties properties, LmdbStoreConfig config,
				boolean sketches) throws IOException, SailException {
			return new LmdbSailStore(data, properties, config, sketches, ValueStore::new,
					(triples, props, configuration, values) -> new TripleStore(triples, props, configuration, values) {
						@Override
						void acknowledgeBackupStages(long transaction) {
							super.acknowledgeBackupStages(transaction);
							if (transaction >= notifyAcknowledgementAt.get()) {
								acknowledgementReached.countDown();
							}
						}
					});
		}
	}
